def get_compendium_list() -> List[Dict[str, Any]]:
    """返回典籍列表（简要信息，供前端目录）"""
    return [
        {
            "id": k,
            "title": v["title"],
            "alt_title": v["alt_title"],
            "author": v["author"],
            "dynasty": v["dynasty"],
            "volume": v["volume"],
            "category": v["category"],
            "level": v["level"],
            "icon": v["icon"],
            "color": v["color"],
            "summary": v["historical_background"][:120] + "...",
        }
        for k, v in CLASSICAL_COMPENDIUM.items()
    ]


def get_compendium_detail(book_id: str) -> Optional[Dict[str, Any]]:
    """根据 ID 返回单本典籍的完整内容"""
    return CLASSICAL_COMPENDIUM.get(book_id)
